/**
 * Emit the stub libSystem images used by the real-clang ObjC fixture.
 *
 * ld64 refuses to link a dynamic executable unless it sees libSystem, and the
 * compatibility layer never loads Apple binaries. The fix is two small dylibs
 * generated by this repository:
 *
 *   libSystem.dylib     link-time only; its install name is Apple's, and it
 *                       declares a dependency on itself so ld64 accepts it.
 *   libSystemShim.dylib runtime stub with no dependencies; the fixture's load
 *                       command is rewritten to @loader_path/libSystemShim.dylib.
 *
 * Both export nothing. The ObjC/runtime symbols the app imports are resolved
 * by the host (`ObjcHost.symbols`), not by these files.
 *
 * Usage: bun scripts/build-objc-shim.ts <output-directory>
 */

import { mkdirSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { words, ret } from "../packages/darwin-compat/src/arm64/assembler.js";
import { buildMachO } from "../packages/darwin-compat/src/macho/build.js";

const directory = resolve(process.argv[2] ?? "fixtures/objc-window/build");
mkdirSync(directory, { recursive: true });

const text = words(ret());
const linkStub = buildMachO({
  fileType: "dylib",
  installName: "/usr/lib/libSystem.B.dylib",
  text,
  exports: [],
  dependencies: [{ name: "/usr/lib/libSystem.B.dylib" }],
});
const runtimeStub = buildMachO({
  fileType: "dylib",
  installName: "@loader_path/libSystemShim.dylib",
  text,
  exports: [],
});

writeFileSync(join(directory, "libSystem.dylib"), linkStub.bytes);
writeFileSync(join(directory, "libSystemShim.dylib"), runtimeStub.bytes);
console.log(`wrote ${join(directory, "libSystem.dylib")} and libSystemShim.dylib`);
